/**
 * Index einmalig beim Modul-Load aufgebaut statt bei jedem Aufruf linear
 * über die 200+ Katalogeinträge zu suchen – `findProductType` wird sehr
 * häufig aufgerufen (u. a. einmal pro Dauerproduktionsauftrag und Tick, bei
 * einem tiefen Kettenaufbau schnell 100-200 Aufträge gleichzeitig).
 */
const PRODUCT_CATALOG_BY_ID = new Map(PRODUCT_CATALOG.map(p => [p.id, p]));

export function findProductType(id: string): ProductType {
  const found = PRODUCT_CATALOG_BY_ID.get(id);
  if (!found) throw new Error(`Unbekannter ProductType: ${id}`);
  return found;
}

export const CONSUMER_GOODS = PRODUCT_CATALOG.filter(p => p.category === 'ConsumerGood');
export const RAW_RESOURCES = PRODUCT_CATALOG.filter(p => p.category === 'RawResource');
export const SHIP_PRODUCTS = PRODUCT_CATALOG.filter(p => p.category === 'Ship');
export const GROUND_UNIT_PRODUCTS = PRODUCT_CATALOG.filter(p => p.category === 'GroundUnit');
export const FACILITY_PRODUCTS = PRODUCT_CATALOG.filter(p => p.category === 'Facility');
